@import url('https://fonts.googleapis.com/css2?family=Black+Han+Sans&family=Nunito:wght:wght@700;900&display=swap');
:root{--ink:#15152e;--yellow:#ffd51c;--cyan:#27d6ed}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{width:100%;height:100%;margin:0;overflow:hidden;background:#7dd8ff;font-family:Nunito,sans-serif}
#game{position:fixed;inset:0;width:100%;height:100%;display:block}
.hidden{display:none!important}.lobby{position:absolute;inset:0;color:white;background:linear-gradient(145deg,#152a76 0 8%,#2d65c9 8% 100%);overflow:hidden}
.lobby:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(255255255,.05) 1px,transparent 1px),linear-gradient(rgba(255255255,.05) 1px,transparent 1px);background-size:44px 44px;mask-image:linear-gradient(to bottom,black,transparent)}
.topbar{height:86px;display:flex;align-items:center;justify-content:space-between;padding:12px 38px;position:relative;border-bottom:3px solid rgba(255,255,255,.12);background:rgba(12,29,92,.45)}
.brand{display:flex;flex-direction:column;font-family:'Black Han Sans',sans-serif;line-height:.73;font-size:26px;transform:rotate(-2deg);text-shadow:3px 4px 0 #7e1d99}.brand span{color:white}.brand strong{font-size:42px;color:#ffcf20;-webkit-text-stroke:2px #ec4d30;letter-spacing:-2px}
.brand-mini{font-family:'Black Han Sans',sans-serif;position:absolute;left:24px;top:16px;font-size:16px;text-shadow:2px 2px #222}.brand-mini span{display:block}.brand-mini b{color:#ffd51c;font-size:25px}
.room-row{display:flex;align-items:center;gap:8px}.icon-btn{width:44px;height:44px;border:2px solid rgba(255,255,255,.45);border-radius:12px;background:#24499f;color:white;font-size:24px;font-weight:900}.icon-btn:active{transform:scale(.95)}
.room-code{height:44px;min-width:145px;border:2px solid rgba(255,255,255,.35);border-radius:12px;background:#1b397f;padding:4px 12px}.room-code small{display:block;font-size9px;opacity:.7}.room-code b{font-size16px;color:#aef4ff}
.lobby-main{position:absolute;inset:86px 0 0;display:grid;grid-template-columns:minmax(220px,280px) 1fr minmax(250px,300px);gap:20px;padding:22px 38px 32px}
.left-panel,.right-panel{position:relative;z-index:2}.panel-title{height:42px;font-size14px;font-weight900;letter-spacing:1.5px;display:flex;align-items:center;gap:8px}.panel-title b{margin-left:auto;color:#b9caff}.live-dot{width9px;height9px;border-radius50%;background:#72ef85;box-shadow:0 0 12px #72ef85}
.player-list{display:flex;flex-direction:column;gap8px}.player-card{height64px;border-radius12px;background:rgba(20,47,119,.88);border:2px solid rgba(255,255,255,.12);display:flex;align-items:center;padding8px;gap10px}.player-card.you{border-color:#ffd51c}.avatar{width46px;height46px;border-radius50%;border:3px solid white;position:relative;overflow:hidden;box-shadow:0 4px 0 rgba(0,0,0,.18)}.avatar:before{content:"";position:absolute;width32px;height22px;border-radius50%;background:#fff3d2;left:7px;top:12px}.avatar:after{content:"";position:absolute;width:36px;height:16px;border-radius:12px 12px 6px 6px;left:5px;bottom:-3px;background:inherit}.player-name{font-size14px;font-weight900}.player-status{font-size10px;color:#91a7df}.ready{color:#79efa0}
.hero-panel{min-width:0;display:flex;flex-direction:column;justify-content:center}.track-preview{height:min(54vh,470px);min-height:310px;border-radius18px;overflow:hidden;position:relative;border:4px solid rgba(255,255,255,.18);background:linear-gradient(#55bff2 0 58%,#44bfe5 58%)}
.sun{position:absolute;width70px;height70px;border-radius50%;background:#fff59b;right:12%;top:9%;box-shadow:0 0 30px #fff}
.cloud{position:absolute;width90px;height20px;border-radius20px;background:white;opacity:.85}.cloud:before,.cloud:after{content:"";position:absolute;border-radius50%;background:white}.cloud:before{width35px;height35px;left12px;bottom0}.cloud:after{width42px;height42px;left38px;bottom0}.c1{left10%;top15%}.c2{right28%;top29%;transform:scale(.7)}
.mountains{position:absolute;left:-5%;right:-5%;bottom:35%;height170px;background:linear-gradient(135deg,transparent 25%,#55ae83 25% 42%,transparent 42%) 0 0/160px 100%,linear-gradient(225deg,transparent 25%,#7ac396 25% 42%,transparent 42%) 0 0/180px 100%;opacity:.8}
.track{position:absolute;left:-10%;right:-10%;bottom:-12%;height58%;background:#f7b54d;clip-path:polygon(12% 35%,88% 35%,100% 100%,0 100%)}.track:before{content:"";position:absolute;inset:20% 14% 0;background:#dfdbca;clip-path:polygon(42% 0,58% 0,100% 100%,0 100%)}.road{position:absolute;inset:24% 28% 0;background:repeating-linear-gradient(90deg,#515a74 0 23%,#777f96 23% 25%);clip-path:polygon(38% 0,62% 0,100% 100%,0 100%);border-top:8px solid #fff}
#previewCanvas{position:absolute;inset:0;width:100%;height:100%}.mode-card{height72px;margin-top10px;border-radius12px;background:rgba(12,35,99,.88);border:2px solid rgba(255,255,255,.12);display:flex;align-items:center;justify-content:space-around}.mode-card div{display:flex;flex-direction:column}.mode-card small{font-size10px;opacity:.65}.mode-card b{font-size15px}
.color-grid{display:grid;grid-template-columns:repeat(5,1fr);gap10px}.color-option{aspect-ratio:1;border:3px solid rgba(255,255,255,.22);border-radius50%;cursor:pointer;position:relative;background:var(--color);box-shadow:inset 0 -10px 0 rgba(0,0,0,.12),0 5px 12px rgba(0,0,0,.15)}.color-option:before{content:"";position:absolute;width44%;height27%;border-radius50%;background:#ffe5b9;left28%;top38%;border:2px solid rgba(0,0,0,.12)}.color-option.selected{border-color:#fff;transform:translateY(-3px);box-shadow:0 0 0 4px #ffd51c,inset 0 -10px 0 rgba(0,0,0,.12)}.color-option.selected:after{content:"✓";position:absolute;width20px;height20px;right:-5px;top:-5px;border-radius50%;background:#ffd51c;color:#302652;text-align:center;font-size14px;font-weight900}
.ready-btn{position:absolute;bottom:0;left:0;right:0;height82px;border:0;border-radius16px;background:linear-gradient(#ffdf38,#ffb617);color:#35234b;box-shadow:0 8px 0 #c85e25,0 14px 25px rgba(0,0,0,.25);font-family:Nunito,sans-serif;cursor:pointer}.ready-btn span{display:block;font-family:'Black Han Sans',sans-serif;font-size28px;transform:rotate(-2deg)}.ready-btn small{display:block;font-size10px}.ready-btn:active{transform:translateY(5px);box-shadow:0 3px 0 #c85e25}
.touch-hint{display:none;position:absolute;bottom:8px;left:50%;transform:translateX(-50%);font-size11px;opacity:.65}
.hud{position:absolute;inset:0;pointer-events:none;z-index:4}.race-info{position:absolute;right:24px;top:18px;text-align:right;text-shadow:2px 3px 0 rgba(0,0,0,.35)}.race-info div:first-child{font-size14px}.race-info div:last-child{font-size26px;color:#ffd51c;font-family:'Black Han Sans',sans-serif}
.countdown{position:absolute;z-index:20;left:50%;top:43%;transform:translate(-50%,-50%);font-family:'Black Han Sans',sans-serif;font-size:min(20vw,180px);color:#ffe52f;-webkit-text-stroke:6px #ed4b42;text-shadow:8px 10px 0 #683a78}
.mobile-controls{position:absolute;z-index:10;inset:0;pointer-events:none}.mobile-controls button{pointer-events:auto}.dpad{position:absolute;left:max(18px,env(safe-area-inset-left));bottom:max(18px,env(safe-area-inset-bottom));display:flex;gap10px}.dpad button,.jump{width68px;height68px;border-radius50%;border:3px solid rgba(255,255,255,.75);background:rgba(19,38,91,.55);color:white;font-size24px}.jump{position:absolute;right:max(22px,env(safe-area-inset-right));bottom:max(20px,env(safe-area-inset-bottom));background:rgba(239,177,28,.75);font-family:'Black Han Sans',sans-serif;font-size26px}
@media(max-width:900px){.topbar{height64px;padding8px 14px}.brand strong{font-size32px}.brand{font-size20px}.lobby-main{inset:64px 0 0;grid-template-columns:170px 1fr 210px;gap10px;padding12px}.track-preview{height:48vh}.ready-btn{height68px}.ready-btn span{font-size22px}.right-panel{min-width:0}.color-grid{gap6px}.player-card{height54px}.avatar{width38px;height38px}.room-code{min-width120px}.room-row{gap5px}}
@media(max-width:680px),(orientation:portrait){.topbar{height58px}.brand strong{font-size28px}.brand{font-size16px}.icon-btn{width38px;height38px}.room-code{height38px}.lobby-main{inset:58px 0 0;grid-template-columns:1fr 170px;padding10px}.left-panel{display:none}.hero-panel{grid-column:1}.track-preview{height:calc(100vh - 165px);min-height:260px}.mode-card{height58px}.right-panel{grid-column:2}.color-grid{grid-template-columns:repeat(2,1fr)}.ready-btn{height64px}.touch-hint{display:block}.copy{display:none}}
@media(max-height:520px){.topbar{height58px}.lobby-main{inset:58px 0 0;padding8px 16px}.track-preview{height:calc(100vh - 150px);min-height:220px}.mode-card{display:none}.left-panel .panel-title,.right-panel>.panel-title{height32px}.player-card{height48px}.ready-btn{height58px}.color-grid{gap5px}}

const colors=[
 ['#ef3b53','Rubi'],['#ff8a22','Laranja'],['#ffd72e','Sol'],['#57d65a','Verdão'],['#27c6dd','Ciano'],
 ['#2774ed','Azul'],['#7c3fe4','Roxo'],['#e84fbb','Pink'],['#ffffff','Branco'],['#2e2e42','Noite']
];
const lobby=document.getElementById('lobby'), canvas=document.getElementById('game'), ctx=canvas.getContext('2d');
const pc=document.getElementById('previewCanvas'), pctx=pc.getContext('2d');
let W,H,DPR,selected=0,running=false,started=false,keys={},last=0;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);pc.width=Math.floor(pc.clientWidth*DPR);pc.height=Math.floor(pc.clientHeight*DPR);pctx.setTransform(DPR,0,0,DPR,0,0)}
addEventListener('resize',resize);resize();

const playerList=document.getElementById('playerList');
function renderLobby(){
 playerList.innerHTML='';
 for(let i=0;i<10;i++){
  const used=i===0||i<1;
  const card=document.createElement('div');card.className='player-card'+(i===0?' you':'');
  if(i<1){card.innerHTML=`<div class="avatar" style="background:${colors[selected][0]}"></div><div><div class="player-name">Você · P1</div><div class="player-status ready">${i===0?'PRONTO':'AGUARDANDO'}</div></div>`}
  else{card.innerHTML=`<div class="avatar" style="opacity:.18;background:#8ba1c9"></div><div><div class="player-name" style="opacity:.32">Slot vazio</div><div class="player-status">ENTRADA P${i+1}</div></div>`}
  playerList.appendChild(card)
 }
 document.getElementById('playerCount').textContent='1/10';
}
const grid=document.getElementById('colorGrid');
colors.forEach((c,i)=>{const b=document.createElement('button');b.className='color-option'+(i===0?' selected':'');b.style.setProperty('--color',c[0]);b.title=c[1];b.onclick=()=>{selected=i;document.querySelectorAll('.color-option').forEach((e,j)=>e.classList.toggle('selected',j===i));renderLobby();};grid.appendChild(b)});
renderLobby();

function drawRunnerPreview(t){
 const w=pc.width/DPR,h=pc.height/DPR;pctx.clearRect(0,0,w,h);
 // small parade of 10 colored silhouettes
 for(let i=0;i<10;i++){const x=w*.16+i*(w*.075),y=h*.73-Math.sin(t*.003+i*.8)*8;drawHero(pctx,x,y,16+i*.25,colors[i][0],t+i*120,false)}
}
function drawHero(c,x,y,s,color,t,outline=true){
 c.save();c.translate(x,y);const bob=Math.sin(t*.008)*2;c.translate(0,bob);
 c.fillStyle='rgba(0,0,0,.18)';c.beginPath();c.ellipse(0,s*.9,s*.8,s*.22,0,0,Math.PI*2);c.fill();
 c.strokeStyle='#24243a';c.lineWidth=Math.max(2,s*.12);
 c.fillStyle='#6a3823';c.fillRect(-s*.42,s*.05,s*.25,s*.85);c.fillRect(s*.17,s*.05,s*.25,s*.85);c.strokeRect(-s*.42,s*.05,s*.25,s*.85);c.strokeRect(s*.17,s*.05,s*.25,s*.85);
 c.fillStyle=color;c.beginPath();c.ellipse(0,s*.05,s*.62,s*.78,0,0,Math.PI*2);c.fill();c.stroke();
 c.fillStyle='#ffe1b5';c.beginPath();c.arc(0,-s*.65,s*.48,0,Math.PI*2);c.fill();c.stroke();
 c.fillStyle='#25253a';c.beginPath();c.arc(-s*.22,-s*.72,s*.07,0,Math.PI*2);c.arc(s*.22,-s*.72,s*.07,0,Math.PI*2);c.fill();
 c.fillStyle=color;c.beginPath();c.moveTo(-s*.48,-s*.82);c.quadraticCurveTo(0,-s*1.45,s*.48,-s*.82);c.quadraticCurveTo(0,-s*1.15,-s*.48,-s*.82);c.fill();c.stroke();
 c.fillStyle='#fff';c.beginPath();c.arc(-s*.23,-s*.82,s*.13,0,Math.PI*2);c.fill();c.fillStyle='#24243a';c.beginPath();c.arc(-s*.23,-s*.82,s*.06,0,Math.PI*2);c.fill();
 c.restore()
}

const course=[
 {x:-400,y:430,w:900,h:250},{x:600,y:430,w:500,h:250},{x:1220,y:370,w:700,h:310},{x:2050,y:430,w:650,h:250},{x:2820,y:360,w:500,h:320},{x:3460,y:430,w:900,h:250},{x:4520,y:430,w:1000,h:250}
];
const player={x:180,y:300,vx:0,vy:0,w:42,h:58,ground:false,cam:0,lap:1};
const coins=[];for(let i=0;i<28;i++)coins.push({x:520+i*150,y:330-Math.sin(i*.8)*90,taken:false});
function platformAt(x,y){return course.find(p=>x>p.x&&x<p.x+p.w&&y>=p.y&&y< p.y+45)}
function startGame(){
 lobby.classList.add('hidden');document.getElementById('hud').classList.remove('hidden');document.getElementById('mobileControls').classList.remove('hidden');running=true;
 player.x=160;player.y=300;player.vx=0;player.vy=0;player.cam=0;player.lap=1;coins.forEach(c=>c.taken=false);
 const cd=document.getElementById('countdown');cd.classList.remove('hidden');let n=3;
 cd.textContent=n;const timer=setInterval(()=>{n--;cd.textContent=n>0?n:'GO!';if(n<0){clearInterval(timer);cd.classList.add('hidden')}},650);
}
document.getElementById('readyBtn').onclick=startGame;
document.getElementById('copyBtn').onclick=()=>navigator.clipboard?.writeText('#RAIN-10');
document.getElementById('soundBtn').onclick=e=>{e.currentTarget.textContent=e.currentTarget.textContent==='♪'?'×':'♪'};
addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(['arrowleft','arrowright','arrowup',' '].includes(e.key.toLower()))e.preventDefault()});
addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.querySelectorAll('[data-control]').forEach(b=>{const k=b.dataset.control==='jump'?'arrowup':b.dataset.control==='left'?'arrowleft':'arrowright';const on=e=>{e.preventPrevent?.();keys[k]=true};const off=e=>{keys[k]=false};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointercancel',off);b.addEventListener('pointerleave',off)});

function update(dt){
 if(!running)return;
 const left=keys.arrowleft||keys.a,right=keys.arrowright||keys.d,jump=keys.arrowup||keys.w||keys[' '];
 if(left)player.vx-=900*dt;if(right)player.vx+=900*dt;player.vx*=Math.pow(.001,dt);player.vx=Math.max(-320,Math.min(420,player.vx));
 if(jump&&player.ground){player.vy=-760;player.ground=false}
 player.vy+=1800*dt;player.x+=player.vx*dt;player.y+=player.vy*dt;
 player.ground=false;
 course.forEach(p=>{if(player.x+player.w/2>p.x&&player.x-player.w/2<p.x+p.w&&player.y+player.h/2>=p.y&&player.y+player.h/2-player.vy*dt<=p.y+15&&player.vy>=0){player.y=p.y-player.h/2;player.vy=0;player.ground=true}});
 if(player.y>800){player.x=Math.max(180,player.x-250);player.y=300;player.vy=0}
 player.x=Math.max(20,player.x);
 if(player.x>5200)player.lap=3;
 player.cam+=(player.x-W*.38-player.cam)*Math.min(1,dt*5);
 coins.forEach(c=>{if(!c.taken&&Math.hypot(player.x-c.x,player.y-c.y)<55)c.taken=true});
 document.getElementById('lapText').textContent=`VOLTAS ${Math.min(3,player.lap)}/3`;
 const pos=Math.max(1,Math.min(10,10-Math.floor(player.x/700)));document.getElementById('positionText').textContent=pos+'º LUGAR';
}
function drawGame(t){
 ctx.clearRect(0,0,W,H);
 const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#58bdf2');g.addColorStop(.58,'#b4e9ef');g.addColorStop(.58,'#45a7c8');g.addColorStop(1,'#14789d');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 ctx.fillStyle='#fff7b0';ctx.beginPath();ctx.arc(W*.82-player.cam*.05,120,55,0,Math.PI*2);ctx.fill();
 ctx.fillStyle='#5da783';ctx.beginPath();ctx.moveTo(-200,430);for(let x=-200;x<W+400;x+=180)ctx.lineTo(x,430-Math.sin(x*.01)*55-100);ctx.lineTo(W+400,520);ctx.closePath();ctx.fill();
 ctx.save();ctx.translate(-player.cam,0);
 course.forEach((p,i)=>{ctx.fillStyle=i%2?'#c88e43':'#d99f4d';ctx.fillRect(p.x,p.y,p.w,p.h);ctx.fillStyle='#f8e6a1';ctx.fillRect(p.x,p.y,p.w,18);ctx.fillStyle='#65b74d';ctx.fillRect(p.x,p.y-18,p.w,22);ctx.fillStyle='#fff';for(let x=p.x+20;x<p.x+p.w;x+=44){ctx.beginPath();ctx.arc(x,p.y-9,7,0,Math.PI*2);ctx.fill()}});
 coins.forEach(c=>{if(c.taken)return;ctx.save();ctx.translate(c.x,c.y+Math.sin(t*.006+c.x)*8);ctx.fillStyle='#ffd83d';ctx.beginPath();ctx.ellipse(0,0,15,21,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#bd751e';ctx.lineWidth=4;ctx.stroke();ctx.restore()});
 drawHero(ctx,player.x,player.y,28,colors[selected][0],t,true);
 ctx.restore();
}
function frame(t){const dt=Math.min(.032,(t-last)/1000||0);last=t;if(running){update(dt);drawGame(t)}else{drawRunnerPreview(t)}requestAnimationFrame(frame)}
requestAnimationFrame(frame);

